{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Atazanavir has an absolute oral bioavailability of 68% (57–80%) in humans, a direct F measurement for a related HIV protease inhibitor with carbamate and branched alkyl features; supports F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Darunavir has an oral bioavailability of 37% when given alone in patients; although often described as low, this is above the 20% threshold and supports high for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Amprenavir is orally bioavailable (>70% in humans) at 900–1200 mg doses, supporting high F for a structurally related HIV protease inhibitor.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "KNI-272 has an absolute oral bioavailability of 29.56±3.50% in fasting patients, a direct absolute F value for a peptidomimetic HIV protease inhibitor; supports F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Lopinavir is reported to have low oral bioavailability in humans; this is the closest analogue, but its cyclic urea/phenoxyacetyl structure and extensive first-pass metabolism make it less transferable to the query's thiazole carbamate/N-methyl urea scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Renin inhibitors such as zankiren have poor oral bioavailability, but this is from a different target class and lower structural similarity, so it is weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F≥20%). The query is a peptidomimetic HIV protease inhibitor with a hydroxyethylene core, two benzyl groups, thiazole carbamate, and N-methyl urea. Multiple related HIV PIs with direct human F measurements—atazanavir 68%, darunavir 37%, amprenavir >70%, KNI-272 ~30–55%—support F≥20%. The closest analogue lopinavir has low F, but its cyclic urea/phenoxyacetyl scaffold and extensive first-pass metabolism are less transferable; the query's thiazole carbamate/N-methyl urea features align with better-absorbed analogues and its CYP3A4-inhibitory character can reduce first-pass loss.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself.",
    "Several literature records use qualitative 'low/poor' labels without numeric F relative to the 20% threshold.",
    "Morgan similarities are modest (≤0.31), limiting quantitative transfer.",
    "No direct data on the query's own P-gp efflux or CYP3A4 auto-inhibition in the retrieved evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

